import sys

def solve():
    import sys
    input = sys.stdin.read().split()
    index = 0
    results = []
    T = int(input[index])
    index += 1
    for _ in range(T):
        N = int(input[index])
        index += 1
        A = list(map(int, input[index:index + N]))
        index += N
        used = [False] * (N + 1)
        P = [-1] * N
        stack = []
        for i in range(N):
            while stack and A[i] != -1 and stack[-1][0] > A[i]:
                stack.pop()
            if A[i] != -1 and (not stack or stack[-1][0] != A[i]):
                results.append(-1)
                break
            P[i] = stack[-1][1] if stack else 0
            used[P[i]] = True
            stack.append((A[i], i + 1))
        else:
            for i in range(N):
                if P[i] == 0:
                    for j in range(1, N + 1):
                        if not used[j]:
                            P[i] = j
                            used[j] = True
                            break
            results.append(P)
    for result in results:
        if result == -1:
            print(-1)
        else:
            print(' '.join(map(str, result)))

solve()
